import React from 'react';
import CanvasLoader from './CanvasLoader';
import { useFrameSequenceLoader } from './frameSequenceLoader';

export default function ScrollCanvasShell({ progress = 0, message = 'Fetching Telemetry & Assets' }) {
  const loaderState = useFrameSequenceLoader();

  return (
    <div
      aria-hidden="true"
      style={{
        position: 'absolute',
        inset: 0,
        width: '100%',
        height: '100%',
        backgroundColor: '#050505',
        overflow: 'hidden',
      }}
    >
      <img
        src="/frames/frame_0001.webp"
        alt=""
        aria-hidden="true"
        loading="eager"
        decoding="async"
        style={{
          position: 'absolute',
          inset: 0,
          width: '100%',
          height: '100%',
          objectFit: 'cover',
          objectPosition: 'center center',
        }}
      />
      <CanvasLoader progress={loaderState.progress || progress} message={message} />
    </div>
  );
}